head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > E > onviewchange]<br/>SearchBox 컴포넌트에서 키보드 또는 마우스 조작을 통해 값이 변경되면 발생합니다.",
    "validation" : [
        "SearchBox 컴포넌트에서 키보드 또는 마우스 조작을 통해 값이 변경되면 onviewchange 이벤트가 발생합니다.",
        "스크립트를 통해 값이 변경된 경우에는 onviewchange 이벤트가 발생하지 않습니다.",
        "info 파라미터로 변경 전후의 값 정보를 담은 객체가 전달됩니다.",
        "info.oldValue 속성으로 변경 전 값이 전달됩니다.",
        "info.newValue 속성으로 변경 후 값이 전달됩니다.",
        "입력값 변경 후 포커스가 빠질 때 'onchange -> onviewchange -> onblur' 순서로 이벤트가 발생합니다.",
        "Reset 버튼 클릭으로 값이 초기화될 때에도 onviewchange 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (Reset 버튼 노출 위해 resetButtonDisplay=show, 초기값 부여)
    let properties = {
        resetButtonDisplay : "show",
        value : "init",
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange", "onviewchange", "onblur"]);

    // searchbox 는 비동기 plugin → await 필수
    await $c.gcm.createBasicSearchBox(cList, eList);
}



// onchange 핸들러 (이벤트 순서 확인용)
scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange 이벤트 발생=====");
};



// onviewchange 핸들러 (e 이외 파라미터 info 는 속성 개별 출력)
scwin.target1_onviewchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onviewchange 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info : " + info);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
};



// onblur 핸들러 (이벤트 순서 확인용)
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur 이벤트 발생=====");
};



// setValue 로 입력값 변경 → onviewchange 발생하지 않음 확인 (스크립트 변경)
scwin.btn_setValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("----- setValue('changedBySetValue') 호출 (onviewchange 미발생 예상) -----");
    target1.setValue("changedBySetValue");
};
